package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.util.*;

/** User-selected Sleep as Android CSV, with review before append. No permission or capture upgrade. */
public final class SleepCsvActivity extends Activity implements SleepCsvJob.Observer {
    private SleepCsvJob job;private final Set<String> selected=new HashSet<>();private String reviewed="",local="";private int page;private Dialog detail;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();job=retained instanceof SleepCsvJob?(SleepCsvJob)retained:new SleepCsvJob(getApplicationContext(),saved!=null);if(saved!=null){reviewed=saved.getString("reviewed","");page=saved.getInt("page");ArrayList<String> list=saved.getStringArrayList("selected");if(list!=null)selected.addAll(list);}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);job.observe(this);}
    @Override public Object onRetainNonConfigurationInstance(){return job;}
    public void changed(SleepCsvJob.State state){if(isDestroyed())return;SleepCsvImport.Review review=state.review;if(review!=null){String key=review.sha256+":"+review.fingerprint;if(!reviewed.equals(key)){reviewed=key;selected.clear();for(SleepCsvImport.Item item:review.items)if(item.eligible())selected.add(item.entry.sourceId);page=0;}}else if(state.phase==SleepCsvJob.Phase.READING){selected.clear();reviewed="";page=0;}
        LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Import Sleep as Android",this::back);Design.space(body,12);Design.text(body,"Reviewed CSV periods",20,600,Design.INK);Design.space(body,8);Design.text(body,"Choose sleep-export.csv, not the vendor ZIP. Imports add historical periods, notes, tags and source time zones. Existing records are never replaced.",14,400,Design.MUTED);
        if(review==null){Design.space(body,10);Design.text(body,"UTF-8 · up to 4 MiB / 2,000 records. Repeated headers and optional noise rows are validated. No measurements or alarms are started.",13,400,Design.MUTED);}else{
            Design.item(body,"plus","New periods",Integer.toString(review.count(SleepCsvImport.Kind.NEW)),null);Design.item(body,"check","Already imported · kept",Integer.toString(review.count(SleepCsvImport.Kind.IDENTICAL)),null);int conflicts=review.count(SleepCsvImport.Kind.SOURCE_CONFLICT)+review.count(SleepCsvImport.Kind.PERIOD_CONFLICT)+review.count(SleepCsvImport.Kind.DELETED);Design.item(body,"info","Conflicts / deleted · kept",Integer.toString(conflicts),null);if(review.repeated>0)Design.text(body,review.repeated+" identical repeated source IDs inside the file are collapsed during review.",12,400,Design.MUTED);Design.text(body,"App duration is the imported period. Vendor adjusted duration / awake aggregates and fractional ratings remain in backed-up source evidence. No awake times, actigraphy, noise measurements or sleep stages are invented.",13,400,Design.MUTED);Design.space(body,6);Design.text(body,"Full original rows are retained privately and in record backups, including any location hash or device/event metadata already in the CSV. Nothing is uploaded.",12,400,Design.MUTED);Design.space(body,8);
            if(!state.busy()){Design.button(body,selected.size()==review.count(SleepCsvImport.Kind.NEW)?"Clear new-period selection":"Select all new periods",false,()->{if(selected.size()==review.count(SleepCsvImport.Kind.NEW))selected.clear();else for(SleepCsvImport.Item item:review.items)if(item.eligible())selected.add(item.entry.sourceId);changed(job.state());});}
            int pages=Math.max(1,(review.items.size()+19)/20);page=Math.max(0,Math.min(page,pages-1));for(int i=page*20;i<Math.min(review.items.size(),(page+1)*20);i++)row(body,review.items.get(i),state.busy());Design.text(body,"Review page "+(page+1)+" of "+pages,12,400,Design.MUTED);if(page>0)Design.button(body,"Previous periods",false,()->{page--;changed(job.state());}).setEnabled(!state.busy());if(page+1<pages)Design.button(body,"Next periods",false,()->{page++;changed(job.state());}).setEnabled(!state.busy());Design.text(body,"Document SHA-256: "+review.sha256,10,400,Design.MUTED);
        }
        Design.space(body,12);if(!state.message.isEmpty())Design.text(body,state.message,14,500,Design.BROWN);if(!local.isEmpty())Design.text(body,local,13,500,Design.BROWN);LinearLayout footer=RecordUi.footer(body);if(state.phase==SleepCsvJob.Phase.REVIEW&&review!=null)Design.button(footer,"Append "+selected.size()+" new periods",true,()->{if(hasWindowFocus()){local="";job.append(selected);}}).setEnabled(!selected.isEmpty());if(!state.busy())Design.button(footer,review==null?"Choose sleep-export.csv":"Choose another CSV",state.phase!=SleepCsvJob.Phase.REVIEW,this::choose);if(state.phase==SleepCsvJob.Phase.READING||state.phase==SleepCsvJob.Phase.APPENDING)Design.button(footer,"Cancel import",false,this::cancel);else if(state.phase!=SleepCsvJob.Phase.CHOOSING)Design.button(footer,"Close",false,this::back);
    }
    private void row(LinearLayout body,SleepCsvImport.Item item,boolean busy){SleepCsvFormat.Entry entry=item.entry;ZoneId zone=ZoneId.of(entry.zone);Design.space(body,14);LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,56));row.setBackground(Design.touch(this,selected.contains(entry.sourceId)?Design.SOFT:android.graphics.Color.TRANSPARENT,10));row.addView(new Design.Icon(this,item.eligible()?(selected.contains(entry.sourceId)?"check":"plus"):"info",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));LinearLayout copy=Design.col(this);Design.text(copy,RecordUi.date(entry.start,zone),15,600,Design.INK);Design.text(copy,RecordUi.preciseClock(this,entry.start,zone)+" – "+RecordUi.preciseClock(this,entry.end,zone)+" · "+entry.zone,12,400,Design.MUTED);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=Design.dp(this,12);row.addView(copy,lp);if(item.eligible()&&!busy){row.setFocusable(true);row.setContentDescription((selected.contains(entry.sourceId)?"Selected ":"Select ")+"source "+entry.sourceId);row.setOnClickListener(v->{if(!selected.remove(entry.sourceId))selected.add(entry.sourceId);changed(job.state());});}body.addView(row);Design.text(body,item.reason,12,500,item.eligible()?Design.MUTED:Design.BROWN);Design.text(body,"Period "+RecordUi.duration(entry.period)+" · vendor adjusted "+(entry.netDuration==null?"unreported":RecordUi.duration(entry.netDuration))+" · rating "+entry.rating.toPlainString(),12,400,Design.MUTED);Design.button(body,"Review source "+entry.sourceId,false,()->show(item)).setEnabled(!busy);Design.line(body);}
    private void show(SleepCsvImport.Item item){if(detail!=null)detail.dismiss();SleepCsvFormat.Entry e=item.entry;detail=SleepPicker.message(this,"Original CSV source","ID: "+e.sourceId+"\n"+item.reason+"\nZone: "+e.zone+"\nPeriod: "+Instant.ofEpochMilli(e.start)+" to "+Instant.ofEpochMilli(e.end)+"\nVendor awake/length adjustment: "+(e.adjustmentMinutes==null?"unreported":e.adjustmentMinutes+" min, placement unknown")+"\nVendor adjusted duration: "+(e.netDuration==null?"unreported":RecordUi.duration(e.netDuration))+"\nOriginal rating: "+e.rating.toPlainString()+" / 5"+(e.fractionalRating()?"; integer app rating stays unset":"")+"\nRetained source values: "+e.actigraphy+" actigraphy, "+e.noise+" noise, "+e.events+" events"+(e.dstResolved?"\nDST overlap resolved from Id + Hours, not a guessed offset.":"")+"\n\nOriginal comment and tags:\n"+e.note+"\n\nRaw source SHA-256: "+e.sha256+"\nAll original fields remain in backed-up source rows; unsupported metrics are not projected as measured data.");}
    private void choose(){if(!hasWindowFocus()||!job.choose())return;local="";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/csv","text/comma-separated-values","application/csv","text/plain","application/octet-stream"}),job.request);}catch(RuntimeException unavailable){job.cancelChoice();local="Android Files could not be opened.";changed(job.state());}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=job.request)return;if(result!=RESULT_OK||data==null){job.cancelChoice();return;}try{if(data.getClipData()!=null&&data.getClipData().getItemCount()>1){job.cancelChoice();return;}job.read(data.getData());}catch(RuntimeException invalid){job.cancelChoice();}}
    private void cancel(){local=job.cancel()?"Cancellation requested. Waiting for the current operation to close.":"The transaction reached its commit boundary. Wait for the final result.";changed(job.state());}
    private void back(){if(job.state().busy()){cancel();return;}finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("reviewed",reviewed);out.putInt("page",page);out.putStringArrayList("selected",new ArrayList<>(selected));}
    @Override protected void onDestroy(){if(detail!=null)detail.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
